import{_ as a,C as s,o as r,c as n,aj as e,E as i}from"./framework.js";const S=JSON.parse('{"title":"基础 · SEO Tab | Cms / Settings / Basic | Documentation","description":"站点级 搜索引擎与 PWA 配置：Lighthouse 优化项、Sitemap 生成、PWA Manifest/Service Worker、是否记录 访问日志、屏蔽 SEO 爬虫、图片 Alt 辅助，以及 Canonical URL 规则。","frontmatter":{"title":"基础 · SEO Tab | Cms / Settings / Basic | Documentation","description":"站点级 搜索引擎与 PWA 配置：Lighthouse 优化项、Sitemap 生成、PWA Manifest/Service Worker、是否记录 访问日志、屏蔽 SEO 爬虫、图片 Alt 辅助，以及 Canonical URL 规则。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/settings/basic/seo.html"}]]},"headers":[],"relativePath":"zh/cms/settings/basic/seo.md","filePath":"cms/settings/basic/seo.md","lastUpdated":1780888357000}'),d={name:"zh/cms/settings/basic/seo.md"};function c(l,t,h,g,m,p){const o=s("DocImage");return r(),n("div",null,[t[0]||(t[0]=e('<h1 id="基础-·-seo-tab" tabindex="-1">基础 · SEO Tab <a class="header-anchor" href="#基础-·-seo-tab" aria-label="Permalink to &quot;基础 · SEO Tab&quot;">​</a></h1><blockquote><p>Tab：<strong>SEO</strong> · <code>name=seo</code><br> 深链：<code>/_Admin/system/settings?SiteId={站点GUID}&amp;name=seo</code></p></blockquote><p>站点级 <strong>搜索引擎与 PWA</strong> 配置：Lighthouse 优化项、<strong>Sitemap</strong> 生成、<strong>PWA</strong> Manifest/Service Worker、是否记录 <strong>访问日志</strong>、屏蔽 SEO 爬虫、图片 <strong>Alt</strong> 辅助，以及 <strong>Canonical URL</strong> 规则。</p>',3)),i(o,{src:"/cms/settings/settings-basic-seo.png",alt:"SEO Tab",width:"1120"}),t[1]||(t[1]=e('<h2 id="lighthouse-优化" tabindex="-1">Lighthouse 优化 <a class="header-anchor" href="#lighthouse-优化" aria-label="Permalink to &quot;Lighthouse 优化&quot;">​</a></h2><p>分组 <strong>Lighthouse 优化</strong>（<code>enableLighthouseOptimization</code>）：按产品内置检查项列表逐项 <strong>启用</strong> 并配置子参数（保存时序列化为 <code>lighthouseSettingsJson</code>）。用于自动注入或调整 HTML 以满足常见性能/SEO 检测项。</p><h2 id="sitemap" tabindex="-1">Sitemap <a class="header-anchor" href="#sitemap" aria-label="Permalink to &quot;Sitemap&quot;">​</a></h2><p>分组 <strong>Sitemap</strong>（<code>sitemapSettings.enable</code>）：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>路径</strong></td><td>站点地图对外路径（如 <code>/sitemap.xml</code>）</td></tr><tr><td><strong>生成方式</strong></td><td><strong>自动</strong> 由系统生成，或 <strong>手动</strong> 编写 TypeScript 代码生成</td></tr><tr><td><strong>编辑代码</strong></td><td>手动模式下打开 Monaco 编辑器编写 sitemap 脚本（<code>sitemapSettings.code</code>）</td></tr></tbody></table><h2 id="pwa" tabindex="-1">PWA <a class="header-anchor" href="#pwa" aria-label="Permalink to &quot;PWA&quot;">​</a></h2><p>分组 <strong>PWA</strong>：配置 <strong>Manifest</strong>（名称、图标等，图标可从 <a href="./../../site/media.html">媒体库</a> 选取）与 <strong>Service Worker</strong> 缓存规则（Method、Pattern、ExpiresIn 等）。保存时分别序列化 <code>pwa.manifest</code> / <code>pwa.serviceWorker</code> JSON。</p><h2 id="其它开关" tabindex="-1">其它开关 <a class="header-anchor" href="#其它开关" aria-label="Permalink to &quot;其它开关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>开关</th><th>说明</th></tr></thead><tbody><tr><td><strong>访问日志</strong></td><td><code>enableVisitorLog</code>：是否记录访客访问（数据在 <a href="./../../operations/visitor-logs.html">运维 · 访问日志</a> 查看）</td></tr><tr><td><strong>阻止 SEO</strong></td><td><code>blockingSeo</code>：限制搜索引擎抓取/索引行为</td></tr><tr><td><strong>启用图片 Alt</strong></td><td><code>enableImageAlt</code>：辅助输出或校验图片 <code>alt</code> 属性</td></tr></tbody></table><h2 id="canonical-url" tabindex="-1">Canonical URL <a class="header-anchor" href="#canonical-url" aria-label="Permalink to &quot;Canonical URL&quot;">​</a></h2><p><strong>Canonical URL</strong> 分组：配置规范链接生成规则，减少重复 URL 对 SEO 的影响（字段以界面为准）。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="./">基础设置概述</a></li><li><a href="./performance.html">性能</a></li><li><a href="./../../operations/visitor-logs.html">运维 · 访问日志</a></li></ul>',13))])}const u=a(d,[["render",c]]);export{S as __pageData,u as default};
